} finalmente {
    escreva("limpeza garantida")
}

var entrada: texto = leia("Digite um número: ")
tente {
    escreva(inteiro(entrada) * 2)
} pegue {
    escreva("Isso não é um inteiro válido")
}

funcao de decorador dobrarResultado(original: funcao): funcao {
    retorna funcao(alvo: qualquer, x: inteiro): inteiro {
        retorna original(alvo, x) * 2
    }
}

@puro
funcao fatorial(n: inteiro): inteiro {
    se n <= 1 { retorna 1 }
    retorna n * fatorial(n - 1)
}
const resultado: inteiro = fatorial(6) // já vira 720 com -o

classe Fabrica {
    estatico criados: inteiro = 0

    estatico proximoId(): inteiro {
        Fabrica.criados++
        retorna Fabrica.criados
    }
}
escreva(Fabrica.proximoId())

